// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_MA: NistCatalogFamily = {"code":"MA","name":"Maintenance","controls":[{"id":"MA-1","oscal_id":"ma-1","family":"MA","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> maintenance policy that:\n    <organization-defined parameter> maintenance policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the maintenance policy and the associated maintenance controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the maintenance policy and procedures; and\nc. Review and update the current maintenance:\n  Review and update the current maintenance:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Maintenance policy and procedures address the controls in the MA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of maintenance policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to maintenance policy and procedures assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"ma-1_prm_1","label":"organization-defined personnel or roles"},{"id":"ma-01_odp.01","label":"personnel or roles"},{"id":"ma-01_odp.02","label":"personnel or roles"},{"id":"ma-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"ma-01_odp.04","label":"official"},{"id":"ma-01_odp.05","label":"frequency"},{"id":"ma-01_odp.06","label":"events"},{"id":"ma-01_odp.07","label":"frequency"},{"id":"ma-01_odp.08","label":"events"}],"objectives":[{"id":"ma-1_obj.a-1","label":"MA-01a.[01]","text":"a maintenance policy is developed and documented;"},{"id":"ma-1_obj.a-2","label":"MA-01a.[02]","text":"the maintenance policy is disseminated to {{ insert: param, ma-01_odp.01 }};"},{"id":"ma-1_obj.a-3","label":"MA-01a.[03]","text":"maintenance procedures to facilitate the implementation of the maintenance policy and associated maintenance controls are developed and documented;"},{"id":"ma-1_obj.a-4","label":"MA-01a.[04]","text":"the maintenance procedures are disseminated to {{ insert: param, ma-01_odp.02 }};"},{"id":"ma-1_obj.a.1.a-1","label":"MA-01a.01(a)[01]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses purpose;"},{"id":"ma-1_obj.a.1.a-2","label":"MA-01a.01(a)[02]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses scope;"},{"id":"ma-1_obj.a.1.a-3","label":"MA-01a.01(a)[03]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses roles;"},{"id":"ma-1_obj.a.1.a-4","label":"MA-01a.01(a)[04]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses responsibilities;"},{"id":"ma-1_obj.a.1.a-5","label":"MA-01a.01(a)[05]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses management commitment;"},{"id":"ma-1_obj.a.1.a-6","label":"MA-01a.01(a)[06]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses coordination among organizational entities;"},{"id":"ma-1_obj.a.1.a-7","label":"MA-01a.01(a)[07]","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy addresses compliance;"},{"id":"ma-1_obj.a.1.b","label":"MA-01a.01(b)","text":"the {{ insert: param, ma-01_odp.03 }} maintenance policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ma-1_obj.b","label":"MA-01b.","text":"the {{ insert: param, ma-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the maintenance policy and procedures;"},{"id":"ma-1_obj.c.1-1","label":"MA-01c.01[01]","text":"the current maintenance policy is reviewed and updated {{ insert: param, ma-01_odp.05 }};"},{"id":"ma-1_obj.c.1-2","label":"MA-01c.01[02]","text":"the current maintenance policy is reviewed and updated following {{ insert: param, ma-01_odp.06 }};"},{"id":"ma-1_obj.c.2-1","label":"MA-01c.02[01]","text":"the current maintenance procedures are reviewed and updated {{ insert: param, ma-01_odp.07 }};"},{"id":"ma-1_obj.c.2-2","label":"MA-01c.02[02]","text":"the current maintenance procedures are reviewed and updated following {{ insert: param, ma-01_odp.08 }}."}],"methods":[{"method":"examine","label":"MA-01-Examine"},{"method":"interview","label":"MA-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"MA-2","oscal_id":"ma-2","family":"MA","title":"Controlled Maintenance","statement":"a. Schedule, document, and review records of maintenance, repair, and replacement on system components in accordance with manufacturer or vendor specifications and/or organizational requirements;\nb. Approve and monitor all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location;\nc. Require that <personnel or roles> explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;\nd. Sanitize equipment to remove the following information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement: <information>;\ne. Check all potentially impacted controls to verify that the controls are still functioning properly following maintenance, repair, or replacement actions; and\nf. Include the following information in organizational maintenance records: <information>.","supplemental_guidance":"Controlling system maintenance addresses the information security aspects of the system maintenance program and applies to all types of maintenance to system components conducted by local or nonlocal entities. Maintenance includes peripherals such as scanners, copiers, and printers. Information necessary for creating effective maintenance records includes the date and time of maintenance, a description of the maintenance performed, names of the individuals or group performing the maintenance, name of the escort, and system components or equipment that are removed or replaced. Organizations consider supply chain-related risks associated with replacement components for systems.","implementation_level":"organization","parameters":[{"id":"ma-02_odp.01","label":"personnel or roles"},{"id":"ma-02_odp.02","label":"information"},{"id":"ma-02_odp.03","label":"information"}],"objectives":[{"id":"ma-2_obj.a-1","label":"MA-02a.[01]","text":"maintenance, repair, and replacement of system components are scheduled in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"id":"ma-2_obj.a-2","label":"MA-02a.[02]","text":"maintenance, repair, and replacement of system components are documented in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"id":"ma-2_obj.a-3","label":"MA-02a.[03]","text":"records of maintenance, repair, and replacement of system components are reviewed in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"id":"ma-2_obj.b-1","label":"MA-02b.[01]","text":"all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are approved;"},{"id":"ma-2_obj.b-2","label":"MA-02b.[02]","text":"all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are monitored;"},{"id":"ma-2_obj.c","label":"MA-02c.","text":"{{ insert: param, ma-02_odp.01 }} is/are required to explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;"},{"id":"ma-2_obj.d","label":"MA-02d.","text":"equipment is sanitized to remove {{ insert: param, ma-02_odp.02 }} from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement;"},{"id":"ma-2_obj.e","label":"MA-02e.","text":"all potentially impacted controls are checked to verify that the controls are still functioning properly following maintenance, repair, or replacement actions;"},{"id":"ma-2_obj.f","label":"MA-02f.","text":"{{ insert: param, ma-02_odp.03 }} is included in organizational maintenance records."}],"methods":[{"method":"examine","label":"MA-02-Examine"},{"method":"interview","label":"MA-02-Interview"},{"method":"test","label":"MA-02-Test"}],"references":[{"title":"OMB A-130"},{"title":"IR 8023"}],"related_controls":["CM-2","CM-3","CM-4","CM-5","CM-8","MA-4","MP-6","PE-16","SI-2","SR-3","SR-4","SR-11"],"enhancements":[{"id":"MA-2(1)","oscal_id":"ma-2.1","family":"MA","title":"Record Content","statement":"","is_enhancement":true,"parent_id":"MA-2"},{"id":"MA-2(2)","oscal_id":"ma-2.2","family":"MA","title":"Automated Maintenance Activities","statement":"(a) Schedule, conduct, and document maintenance, repair, and replacement actions for the system using <organization-defined automated mechanisms> ; and\n(b) Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed.","supplemental_guidance":"The use of automated mechanisms to manage and control system maintenance programs and activities helps to ensure the generation of timely, accurate, complete, and consistent maintenance records.","implementation_level":"organization","parameters":[{"id":"ma-2.2_prm_1","label":"organization-defined automated mechanisms"},{"id":"ma-02.02_odp.01","label":"automated mechanisms"},{"id":"ma-02.02_odp.02","label":"automated mechanisms"},{"id":"ma-02.02_odp.03","label":"automated mechanisms"}],"objectives":[{"id":"ma-2.2_obj.a-1","label":"MA-02(02)(a)[01]","text":"{{ insert: param, ma-02.02_odp.01 }} are used to schedule maintenance, repair, and replacement actions for the system;"},{"id":"ma-2.2_obj.a-2","label":"MA-02(02)(a)[02]","text":"{{ insert: param, ma-02.02_odp.02 }} are used to conduct maintenance, repair, and replacement actions for the system;"},{"id":"ma-2.2_obj.a-3","label":"MA-02(02)(a)[03]","text":"{{ insert: param, ma-02.02_odp.03 }} are used to document maintenance, repair, and replacement actions for the system;"},{"id":"ma-2.2_obj.b-1","label":"MA-02(02)(b)[01]","text":"up-to date, accurate, and complete records of all maintenance actions requested, scheduled, in process, and completed are produced."},{"id":"ma-2.2_obj.b-2","label":"MA-02(02)(b)[02]","text":"up-to date, accurate, and complete records of all repair actions requested, scheduled, in process, and completed are produced."},{"id":"ma-2.2_obj.b-3","label":"MA-02(02)(b)[03]","text":"up-to date, accurate, and complete records of all replacement actions requested, scheduled, in process, and completed are produced."}],"methods":[{"method":"examine","label":"MA-02(02)-Examine"},{"method":"interview","label":"MA-02(02)-Interview"},{"method":"test","label":"MA-02(02)-Test"}],"related_controls":["MA-3"],"is_enhancement":true,"parent_id":"MA-2"}]},{"id":"MA-3","oscal_id":"ma-3","family":"MA","title":"Maintenance Tools","statement":"a. Approve, control, and monitor the use of system maintenance tools; and\nb. Review previously approved system maintenance tools <frequency>.","supplemental_guidance":"Approving, controlling, monitoring, and reviewing maintenance tools address security-related issues associated with maintenance tools that are not within system authorization boundaries and are used specifically for diagnostic and repair actions on organizational systems. Organizations have flexibility in determining roles for the approval of maintenance tools and how that approval is documented. A periodic review of maintenance tools facilitates the withdrawal of approval for outdated, unsupported, irrelevant, or no-longer-used tools. Maintenance tools can include hardware, software, and firmware items and may be pre-installed, brought in with maintenance personnel on media, cloud-based, or downloaded from a website. Such tools can be vehicles for transporting malicious code, either intentionally or unintentionally, into a facility and subsequently into systems. Maintenance tools can include hardware and software diagnostic test equipment and packet sniffers. The hardware and software components that support maintenance and are a part of the system (including the software implementing utilities such as \"ping,\" \"ls,\" \"ipconfig,\" or the hardware and software implementing the monitoring port of an Ethernet switch) are not addressed by maintenance tools.","implementation_level":"organization","parameters":[{"id":"ma-03_odp","label":"frequency"}],"objectives":[{"id":"ma-3_obj.a-1","label":"MA-03a.[01]","text":"the use of system maintenance tools is approved;"},{"id":"ma-3_obj.a-2","label":"MA-03a.[02]","text":"the use of system maintenance tools is controlled;"},{"id":"ma-3_obj.a-3","label":"MA-03a.[03]","text":"the use of system maintenance tools is monitored;"},{"id":"ma-3_obj.b","label":"MA-03b.","text":"previously approved system maintenance tools are reviewed {{ insert: param, ma-03_odp }}."}],"methods":[{"method":"examine","label":"MA-03-Examine"},{"method":"interview","label":"MA-03-Interview"},{"method":"test","label":"MA-03-Test"}],"references":[{"title":"SP 800-88"}],"related_controls":["MA-2","PE-16"],"enhancements":[{"id":"MA-3(1)","oscal_id":"ma-3.1","family":"MA","title":"Inspect Tools","statement":"Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications.","supplemental_guidance":"Maintenance tools can be directly brought into a facility by maintenance personnel or downloaded from a vendor’s website. If, upon inspection of the maintenance tools, organizations determine that the tools have been modified in an improper manner or the tools contain malicious code, the incident is handled consistent with organizational policies and procedures for incident handling.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-03(01)-Examine"},{"method":"interview","label":"MA-03(01)-Interview"},{"method":"test","label":"MA-03(01)-Test"}],"related_controls":["SI-7"],"is_enhancement":true,"parent_id":"MA-3"},{"id":"MA-3(2)","oscal_id":"ma-3.2","family":"MA","title":"Inspect Media","statement":"Check media containing diagnostic and test programs for malicious code before the media are used in the system.","supplemental_guidance":"If, upon inspection of media containing maintenance, diagnostic, and test programs, organizations determine that the media contains malicious code, the incident is handled consistent with organizational incident handling policies and procedures.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-03(02)-Examine"},{"method":"interview","label":"MA-03(02)-Interview"},{"method":"test","label":"MA-03(02)-Test"}],"related_controls":["SI-3"],"is_enhancement":true,"parent_id":"MA-3"},{"id":"MA-3(3)","oscal_id":"ma-3.3","family":"MA","title":"Prevent Unauthorized Removal","statement":"Prevent the removal of maintenance equipment containing organizational information by:\n(a) Verifying that there is no organizational information contained on the equipment;\n(b) Sanitizing or destroying the equipment;\n(c) Retaining the equipment within the facility; or\n(d) Obtaining an exemption from <personnel or roles> explicitly authorizing removal of the equipment from the facility.","supplemental_guidance":"Organizational information includes all information owned by organizations and any information provided to organizations for which the organizations serve as information stewards.","implementation_level":"organization","parameters":[{"id":"ma-03.03_odp","label":"personnel or roles"}],"objectives":[{"id":"ma-3.3_obj.a","label":"MA-03(03)(a)","text":"the removal of maintenance equipment containing organizational information is prevented by verifying that there is no organizational information contained on the equipment; or"},{"id":"ma-3.3_obj.b","label":"MA-03(03)(b)","text":"the removal of maintenance equipment containing organizational information is prevented by sanitizing or destroying the equipment; or"},{"id":"ma-3.3_obj.c","label":"MA-03(03)(c)","text":"the removal of maintenance equipment containing organizational information is prevented by retaining the equipment within the facility; or"},{"id":"ma-3.3_obj.d","label":"MA-03(03)(d)","text":"the removal of maintenance equipment containing organizational information is prevented by obtaining an exemption from {{ insert: param, ma-03.03_odp }} explicitly authorizing removal of the equipment from the facility."}],"methods":[{"method":"examine","label":"MA-03(03)-Examine"},{"method":"interview","label":"MA-03(03)-Interview"},{"method":"test","label":"MA-03(03)-Test"}],"related_controls":["MP-6"],"is_enhancement":true,"parent_id":"MA-3"},{"id":"MA-3(4)","oscal_id":"ma-3.4","family":"MA","title":"Restricted Tool Use","statement":"Restrict the use of maintenance tools to authorized personnel only.","supplemental_guidance":"Restricting the use of maintenance tools to only authorized personnel applies to systems that are used to carry out maintenance functions.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-03(04)-Examine"},{"method":"interview","label":"MA-03(04)-Interview"},{"method":"test","label":"MA-03(04)-Test"}],"related_controls":["AC-3","AC-5","AC-6"],"is_enhancement":true,"parent_id":"MA-3"},{"id":"MA-3(5)","oscal_id":"ma-3.5","family":"MA","title":"Execution with Privilege","statement":"Monitor the use of maintenance tools that execute with increased privilege.","supplemental_guidance":"Maintenance tools that execute with increased system privilege can result in unauthorized access to organizational information and assets that would otherwise be inaccessible.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-03(05)-Examine"},{"method":"interview","label":"MA-03(05)-Interview"},{"method":"test","label":"MA-03(05)-Test"}],"related_controls":["AC-3","AC-6"],"is_enhancement":true,"parent_id":"MA-3"},{"id":"MA-3(6)","oscal_id":"ma-3.6","family":"MA","title":"Software Updates and Patches","statement":"Inspect maintenance tools to ensure the latest software updates and patches are installed.","supplemental_guidance":"Maintenance tools using outdated and/or unpatched software can provide a threat vector for adversaries and result in a significant vulnerability for organizations.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-03(06)-Examine"},{"method":"interview","label":"MA-03(06)-Interview"},{"method":"test","label":"MA-03(06)-Test"}],"related_controls":["AC-3","AC-6"],"is_enhancement":true,"parent_id":"MA-3"}]},{"id":"MA-4","oscal_id":"ma-4","family":"MA","title":"Nonlocal Maintenance","statement":"a. Approve and monitor nonlocal maintenance and diagnostic activities;\nb. Allow the use of nonlocal maintenance and diagnostic tools only as consistent with organizational policy and documented in the security plan for the system;\nc. Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions;\nd. Maintain records for nonlocal maintenance and diagnostic activities; and\ne. Terminate session and network connections when nonlocal maintenance is completed.","supplemental_guidance":"Nonlocal maintenance and diagnostic activities are conducted by individuals who communicate through either an external or internal network. Local maintenance and diagnostic activities are carried out by individuals who are physically present at the system location and not communicating across a network connection. Authentication techniques used to establish nonlocal maintenance and diagnostic sessions reflect the network access requirements in [IA-2](#ia-2) . Strong authentication requires authenticators that are resistant to replay attacks and employ multi-factor authentication. Strong authenticators include PKI where certificates are stored on a token protected by a password, passphrase, or biometric. Enforcing requirements in [MA-4](#ma-4) is accomplished, in part, by other controls. [SP 800-63B](#e59c5a7c-8b1f-49ca-8de0-6ee0882180ce) provides additional guidance on strong authentication and authenticators.","implementation_level":"organization","objectives":[{"id":"ma-4_obj.a-1","label":"MA-04a.[01]","text":"nonlocal maintenance and diagnostic activities are approved;"},{"id":"ma-4_obj.a-2","label":"MA-04a.[02]","text":"nonlocal maintenance and diagnostic activities are monitored;"},{"id":"ma-4_obj.b-1","label":"MA-04b.[01]","text":"the use of nonlocal maintenance and diagnostic tools are allowed only as consistent with organizational policy;"},{"id":"ma-4_obj.b-2","label":"MA-04b.[02]","text":"the use of nonlocal maintenance and diagnostic tools are documented in the security plan for the system;"},{"id":"ma-4_obj.c","label":"MA-04c.","text":"strong authentication is employed in the establishment of nonlocal maintenance and diagnostic sessions;"},{"id":"ma-4_obj.d","label":"MA-04d.","text":"records for nonlocal maintenance and diagnostic activities are maintained;"},{"id":"ma-4_obj.e-1","label":"MA-04e.[01]","text":"session connections are terminated when nonlocal maintenance is completed;"},{"id":"ma-4_obj.e-2","label":"MA-04e.[02]","text":"network connections are terminated when nonlocal maintenance is completed."}],"methods":[{"method":"examine","label":"MA-04-Examine"},{"method":"interview","label":"MA-04-Interview"},{"method":"test","label":"MA-04-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 197"},{"title":"FIPS 201-2"},{"title":"SP 800-63-3"},{"title":"SP 800-88"}],"related_controls":["AC-2","AC-3","AC-6","AC-17","AU-2","AU-3","IA-2","IA-4","IA-5","IA-8","MA-2","MA-5","PL-2","SC-7","SC-10"],"enhancements":[{"id":"MA-4(1)","oscal_id":"ma-4.1","family":"MA","title":"Logging and Review","statement":"(a) Log <organization-defined audit events> for nonlocal maintenance and diagnostic sessions; and\n(b) Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior.","supplemental_guidance":"Audit logging for nonlocal maintenance is enforced by [AU-2](#au-2) . Audit events are defined in [AU-2a](#au-2_smt.a).","implementation_level":"organization","parameters":[{"id":"ma-4.1_prm_1","label":"organization-defined audit events"},{"id":"ma-04.01_odp.01","label":"audit events"},{"id":"ma-04.01_odp.02","label":"audit events"}],"objectives":[{"id":"ma-4.1_obj.a-1","label":"MA-04(01)(a)[01]","text":"{{ insert: param, ma-04.01_odp.01 }} are logged for nonlocal maintenance sessions;"},{"id":"ma-4.1_obj.a-2","label":"MA-04(01)(a)[02]","text":"{{ insert: param, ma-04.01_odp.02 }} are logged for nonlocal diagnostic sessions;"},{"id":"ma-4.1_obj.b-1","label":"MA-04(01)(b)[01]","text":"the audit records of the maintenance sessions are reviewed to detect anomalous behavior;"},{"id":"ma-4.1_obj.b-2","label":"MA-04(01)(b)[02]","text":"the audit records of the diagnostic sessions are reviewed to detect anomalous behavior."}],"methods":[{"method":"examine","label":"MA-04(01)-Examine"},{"method":"interview","label":"MA-04(01)-Interview"},{"method":"test","label":"MA-04(01)-Test"}],"related_controls":["AU-6","AU-12"],"is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(2)","oscal_id":"ma-4.2","family":"MA","title":"Document Nonlocal Maintenance","statement":"","is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(3)","oscal_id":"ma-4.3","family":"MA","title":"Comparable Security and Sanitization","statement":"(a) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or\n(b) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system.","supplemental_guidance":"Comparable security capability on systems, diagnostic tools, and equipment providing maintenance services implies that the implemented controls on those systems, tools, and equipment are at least as comprehensive as the controls on the system being serviced.","implementation_level":"organization","objectives":[{"id":"ma-4.3_obj.a-1","label":"MA-04(03)(a)[01]","text":"nonlocal maintenance services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced;"},{"id":"ma-4.3_obj.a-2","label":"MA-04(03)(a)[02]","text":"nonlocal diagnostic services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or"},{"id":"ma-4.3_obj.b-1","label":"MA-04(03)(b)[01]","text":"the component to be serviced is removed from the system prior to nonlocal maintenance or diagnostic services;"},{"id":"ma-4.3_obj.b-2","label":"MA-04(03)(b)[02]","text":"the component to be serviced is sanitized (for organizational information);"},{"id":"ma-4.3_obj.b-3","label":"MA-04(03)(b)[03]","text":"the component is inspected and sanitized (for potentially malicious software) after the service is performed and before reconnecting the component to the system."}],"methods":[{"method":"examine","label":"MA-04(03)-Examine"},{"method":"interview","label":"MA-04(03)-Interview"},{"method":"test","label":"MA-04(03)-Test"}],"related_controls":["MP-6","SI-3","SI-7"],"is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(4)","oscal_id":"ma-4.4","family":"MA","title":"Authentication and Separation of Maintenance Sessions","statement":"Protect nonlocal maintenance sessions by:\n(a) Employing <authenticators that are replay resistant> ; and\n(b) Separating the maintenance sessions from other network sessions with the system by either:\n  Separating the maintenance sessions from other network sessions with the system by either:\n  (1) Physically separated communications paths; or\n  (2) Logically separated communications paths.","supplemental_guidance":"Communications paths can be logically separated using encryption.","implementation_level":"organization","parameters":[{"id":"ma-04.04_odp","label":"authenticators that are replay resistant"}],"objectives":[{"id":"ma-4.4_obj.a","label":"MA-04(04)(a)","text":"nonlocal maintenance sessions are protected by employing {{ insert: param, ma-04.04_odp }};"},{"id":"ma-4.4_obj.b.1","label":"MA-04(04)(b)(01)","text":"nonlocal maintenance sessions are protected by separating maintenance sessions from other network sessions with the system by physically separated communication paths; or"},{"id":"ma-4.4_obj.b.2","label":"MA-04(04)(b)(02)","text":"nonlocal maintenance sessions are protected by logically separated communication paths."}],"methods":[{"method":"examine","label":"MA-04(04)-Examine"},{"method":"interview","label":"MA-04(04)-Interview"},{"method":"test","label":"MA-04(04)-Test"}],"is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(5)","oscal_id":"ma-4.5","family":"MA","title":"Approvals and Notifications","statement":"(a) Require the approval of each nonlocal maintenance session by <personnel or roles> ; and\n(b) Notify the following personnel or roles of the date and time of planned nonlocal maintenance: <personnel and roles>.","supplemental_guidance":"Notification may be performed by maintenance personnel. Approval of nonlocal maintenance is accomplished by personnel with sufficient information security and system knowledge to determine the appropriateness of the proposed maintenance.","implementation_level":"organization","parameters":[{"id":"ma-04.05_odp.01","label":"personnel or roles"},{"id":"ma-04.05_odp.02","label":"personnel and roles"}],"objectives":[{"id":"ma-4.5_obj.a","label":"MA-04(05)(a)","text":"the approval of each nonlocal maintenance session is required by {{ insert: param, ma-04.05_odp.01 }};"},{"id":"ma-4.5_obj.b","label":"MA-04(05)(b)","text":"{{ insert: param, ma-04.05_odp.02 }} is/are notified of the date and time of planned nonlocal maintenance."}],"methods":[{"method":"examine","label":"MA-04(05)-Examine"},{"method":"interview","label":"MA-04(05)-Interview"},{"method":"test","label":"MA-04(05)-Test"}],"is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(6)","oscal_id":"ma-4.6","family":"MA","title":"Cryptographic Protection","statement":"Implement the following cryptographic mechanisms to protect the integrity and confidentiality of nonlocal maintenance and diagnostic communications: <cryptographic mechanisms>.","supplemental_guidance":"Failure to protect nonlocal maintenance and diagnostic communications can result in unauthorized individuals gaining access to organizational information. Unauthorized access during remote maintenance sessions can result in a variety of hostile actions, including malicious code insertion, unauthorized changes to system parameters, and exfiltration of organizational information. Such actions can result in the loss or degradation of mission or business capabilities.","implementation_level":"organization","parameters":[{"id":"ma-04.06_odp","label":"cryptographic mechanisms"}],"objectives":[{"id":"ma-4.6_obj-1","label":"MA-04(06)[01]","text":"{{ insert: param, ma-04.06_odp }} are implemented to protect the integrity of nonlocal maintenance and diagnostic communications;"},{"id":"ma-4.6_obj-2","label":"MA-04(06)[02]","text":"{{ insert: param, ma-04.06_odp }} are implemented to protect the confidentiality of nonlocal maintenance and diagnostic communications."}],"methods":[{"method":"examine","label":"MA-04(06)-Examine"},{"method":"interview","label":"MA-04(06)-Interview"},{"method":"test","label":"MA-04(06)-Test"}],"related_controls":["SC-8","SC-12","SC-13"],"is_enhancement":true,"parent_id":"MA-4"},{"id":"MA-4(7)","oscal_id":"ma-4.7","family":"MA","title":"Disconnect Verification","statement":"Verify session and network connection termination after the completion of nonlocal maintenance and diagnostic sessions.","supplemental_guidance":"Verifying the termination of a connection once maintenance is completed ensures that connections established during nonlocal maintenance and diagnostic sessions have been terminated and are no longer available for use.","implementation_level":"system","objectives":[{"id":"ma-4.7_obj-1","label":"MA-04(07)[01]","text":"session connection termination is verified after the completion of nonlocal maintenance and diagnostic sessions;"},{"id":"ma-4.7_obj-2","label":"MA-04(07)[02]","text":"network connection termination is verified after the completion of nonlocal maintenance and diagnostic sessions."}],"methods":[{"method":"examine","label":"MA-04(07)-Examine"},{"method":"interview","label":"MA-04(07)-Interview"},{"method":"test","label":"MA-04(07)-Test"}],"related_controls":["AC-12"],"is_enhancement":true,"parent_id":"MA-4"}]},{"id":"MA-5","oscal_id":"ma-5","family":"MA","title":"Maintenance Personnel","statement":"a. Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel;\nb. Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; and\nc. Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations.","supplemental_guidance":"Maintenance personnel refers to individuals who perform hardware or software maintenance on organizational systems, while [PE-2](#pe-2) addresses physical access for individuals whose maintenance duties place them within the physical protection perimeter of the systems. Technical competence of supervising individuals relates to the maintenance performed on the systems, while having required access authorizations refers to maintenance on and near the systems. Individuals not previously identified as authorized maintenance personnel—such as information technology manufacturers, vendors, systems integrators, and consultants—may require privileged access to organizational systems, such as when they are required to conduct maintenance activities with little or no notice. Based on organizational assessments of risk, organizations may issue temporary credentials to these individuals. Temporary credentials may be for one-time use or for very limited time periods.","implementation_level":"organization","objectives":[{"id":"ma-5_obj.a-1","label":"MA-05a.[01]","text":"a process for maintenance personnel authorization is established;"},{"id":"ma-5_obj.a-2","label":"MA-05a.[02]","text":"a list of authorized maintenance organizations or personnel is maintained;"},{"id":"ma-5_obj.b","label":"MA-05b.","text":"non-escorted personnel performing maintenance on the system possess the required access authorizations;"},{"id":"ma-5_obj.c","label":"MA-05c.","text":"organizational personnel with required access authorizations and technical competence is/are designated to supervise the maintenance activities of personnel who do not possess the required access authorizations."}],"methods":[{"method":"examine","label":"MA-05-Examine"},{"method":"interview","label":"MA-05-Interview"},{"method":"test","label":"MA-05-Test"}],"related_controls":["AC-2","AC-3","AC-5","AC-6","IA-2","IA-8","MA-4","MP-2","PE-2","PE-3","PS-7","RA-3"],"enhancements":[{"id":"MA-5(1)","oscal_id":"ma-5.1","family":"MA","title":"Individuals Without Appropriate Access","statement":"(a) Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:\n  Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:\n  (1) Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified; and\n  (2) Prior to initiating maintenance or diagnostic activities by personnel who do not have needed access authorizations, clearances or formal access approvals, all volatile information storage components within the system are sanitized and all nonvolatile storage media are removed or physically disconnected from the system and secured; and\n(b) Develop and implement <alternate controls> in the event a system component cannot be sanitized, removed, or disconnected from the system.","supplemental_guidance":"Procedures for individuals who lack appropriate security clearances or who are not U.S. citizens are intended to deny visual and electronic access to classified or controlled unclassified information contained on organizational systems. Procedures for the use of maintenance personnel can be documented in security plans for the systems.","implementation_level":"organization","parameters":[{"id":"ma-05.01_odp","label":"alternate controls"}],"objectives":[{"id":"ma-5.1_obj.a.1","label":"MA-05(01)(a)(01)","text":"procedures for the use of maintenance personnel who lack appropriate security clearances or are not U.S. citizens are implemented and include approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified escorting and supervising maintenance personnel without the needed access authorization during the performance of maintenance and diagnostic activities;"},{"id":"ma-5.1_obj.a.2","label":"MA-05(01)(a)(02)","text":"procedures for the use of maintenance personnel who lack appropriate security clearances or are not U.S. citizens are implemented and include all volatile information storage components within the system being sanitized and all non-volatile storage media being removed or physically disconnected from the system and secured prior to initiating maintenance or diagnostic activities;"},{"id":"ma-5.1_obj.b","label":"MA-05(01)(b)","text":"{{ insert: param, ma-05.01_odp }} are developed and implemented in the event that a system cannot be sanitized, removed, or disconnected from the system."}],"methods":[{"method":"examine","label":"MA-05(01)-Examine"},{"method":"interview","label":"MA-05(01)-Interview"},{"method":"test","label":"MA-05(01)-Test"}],"related_controls":["MP-6","PL-2"],"is_enhancement":true,"parent_id":"MA-5"},{"id":"MA-5(2)","oscal_id":"ma-5.2","family":"MA","title":"Security Clearances for Classified Systems","statement":"Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information possess security clearances and formal access approvals for at least the highest classification level and for compartments of information on the system.","supplemental_guidance":"Personnel who conduct maintenance on organizational systems may be exposed to classified information during the course of their maintenance activities. To mitigate the inherent risk of such exposure, organizations use maintenance personnel that are cleared (i.e., possess security clearances) to the classification level of the information stored on the system.","implementation_level":"organization","objectives":[{"id":"ma-5.2_obj-1","label":"MA-05(02)[01]","text":"personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information possess security clearances for at least the highest classification level and for compartments of information on the system;"},{"id":"ma-5.2_obj-2","label":"MA-05(02)[02]","text":"personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information possess formal access approvals for at least the highest classification level and for compartments of information on the system."}],"methods":[{"method":"examine","label":"MA-05(02)-Examine"},{"method":"interview","label":"MA-05(02)-Interview"},{"method":"test","label":"MA-05(02)-Test"}],"related_controls":["PS-3"],"is_enhancement":true,"parent_id":"MA-5"},{"id":"MA-5(3)","oscal_id":"ma-5.3","family":"MA","title":"Citizenship Requirements for Classified Systems","statement":"Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information are U.S. citizens.","supplemental_guidance":"Personnel who conduct maintenance on organizational systems may be exposed to classified information during the course of their maintenance activities. If access to classified information on organizational systems is restricted to U.S. citizens, the same restriction is applied to personnel performing maintenance on those systems.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-05(03)-Examine"},{"method":"interview","label":"MA-05(03)-Interview"}],"related_controls":["PS-3"],"is_enhancement":true,"parent_id":"MA-5"},{"id":"MA-5(4)","oscal_id":"ma-5.4","family":"MA","title":"Foreign Nationals","statement":"Ensure that:\n(a) Foreign nationals with appropriate security clearances are used to conduct maintenance and diagnostic activities on classified systems only when the systems are jointly owned and operated by the United States and foreign allied governments, or owned and operated solely by foreign allied governments; and\n(b) Approvals, consents, and detailed operational conditions regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements.","supplemental_guidance":"Personnel who conduct maintenance and diagnostic activities on organizational systems may be exposed to classified information. If non-U.S. citizens are permitted to perform maintenance and diagnostics activities on classified systems, then additional vetting is required to ensure agreements and restrictions are not being violated.","implementation_level":"organization","objectives":[{"id":"ma-5.4_obj.a","label":"MA-05(04)(a)","text":"foreign nationals with appropriate security clearances are used to conduct maintenance and diagnostic activities on classified systems only when the systems are jointly owned and operated by the United States and foreign allied governments or owned and operated solely by foreign allied governments;"},{"id":"ma-5.4_obj.b-1","label":"MA-05(04)(b)[01]","text":"approvals regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements;"},{"id":"ma-5.4_obj.b-2","label":"MA-05(04)(b)[02]","text":"consents regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements;"},{"id":"ma-5.4_obj.b-3","label":"MA-05(04)(b)[03]","text":"detailed operational conditions regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements."}],"methods":[{"method":"examine","label":"MA-05(04)-Examine"},{"method":"interview","label":"MA-05(04)-Interview"},{"method":"test","label":"MA-05(04)-Test"}],"related_controls":["PS-3"],"is_enhancement":true,"parent_id":"MA-5"},{"id":"MA-5(5)","oscal_id":"ma-5.5","family":"MA","title":"Non-system Maintenance","statement":"Ensure that non-escorted personnel performing maintenance activities not directly associated with the system but in the physical proximity of the system, have required access authorizations.","supplemental_guidance":"Personnel who perform maintenance activities in other capacities not directly related to the system include physical plant personnel and custodial personnel.","implementation_level":"organization","methods":[{"method":"examine","label":"MA-05(05)-Examine"},{"method":"interview","label":"MA-05(05)-Interview"}],"is_enhancement":true,"parent_id":"MA-5"}]},{"id":"MA-6","oscal_id":"ma-6","family":"MA","title":"Timely Maintenance","statement":"Obtain maintenance support and/or spare parts for <system components> within <time period> of failure.","supplemental_guidance":"Organizations specify the system components that result in increased risk to organizational operations and assets, individuals, other organizations, or the Nation when the functionality provided by those components is not operational. Organizational actions to obtain maintenance support include having appropriate contracts in place.","implementation_level":"organization","parameters":[{"id":"ma-06_odp.01","label":"system components"},{"id":"ma-06_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"MA-06-Examine"},{"method":"interview","label":"MA-06-Interview"},{"method":"test","label":"MA-06-Test"}],"related_controls":["CM-8","CP-2","CP-7","RA-7","SA-15","SI-13","SR-2","SR-3","SR-4"],"enhancements":[{"id":"MA-6(1)","oscal_id":"ma-6.1","family":"MA","title":"Preventive Maintenance","statement":"Perform preventive maintenance on <system components> at <time intervals>.","supplemental_guidance":"Preventive maintenance includes proactive care and the servicing of system components to maintain organizational equipment and facilities in satisfactory operating condition. Such maintenance provides for the systematic inspection, tests, measurements, adjustments, parts replacement, detection, and correction of incipient failures either before they occur or before they develop into major defects. The primary goal of preventive maintenance is to avoid or mitigate the consequences of equipment failures. Preventive maintenance is designed to preserve and restore equipment reliability by replacing worn components before they fail. Methods of determining what preventive (or other) failure management policies to apply include original equipment manufacturer recommendations; statistical failure records; expert opinion; maintenance that has already been conducted on similar equipment; requirements of codes, laws, or regulations within a jurisdiction; or measured values and performance indications.","implementation_level":"organization","parameters":[{"id":"ma-06.01_odp.01","label":"system components"},{"id":"ma-06.01_odp.02","label":"time intervals"}],"methods":[{"method":"examine","label":"MA-06(01)-Examine"},{"method":"interview","label":"MA-06(01)-Interview"},{"method":"test","label":"MA-06(01)-Test"}],"is_enhancement":true,"parent_id":"MA-6"},{"id":"MA-6(2)","oscal_id":"ma-6.2","family":"MA","title":"Predictive Maintenance","statement":"Perform predictive maintenance on <system components> at <time intervals>.","supplemental_guidance":"Predictive maintenance evaluates the condition of equipment by performing periodic or continuous (online) equipment condition monitoring. The goal of predictive maintenance is to perform maintenance at a scheduled time when the maintenance activity is most cost-effective and before the equipment loses performance within a threshold. The predictive component of predictive maintenance stems from the objective of predicting the future trend of the equipment's condition. The predictive maintenance approach employs principles of statistical process control to determine at what point in the future maintenance activities will be appropriate. Most predictive maintenance inspections are performed while equipment is in service, thus minimizing disruption of normal system operations. Predictive maintenance can result in substantial cost savings and higher system reliability.","implementation_level":"organization","parameters":[{"id":"ma-06.02_odp.01","label":"system components"},{"id":"ma-06.02_odp.02","label":"time intervals"}],"methods":[{"method":"examine","label":"MA-06(02)-Examine"},{"method":"interview","label":"MA-06(02)-Interview"},{"method":"test","label":"MA-06(02)-Test"}],"is_enhancement":true,"parent_id":"MA-6"},{"id":"MA-6(3)","oscal_id":"ma-6.3","family":"MA","title":"Automated Support for Predictive Maintenance","statement":"Transfer predictive maintenance data to a maintenance management system using <automated mechanisms>.","supplemental_guidance":"A computerized maintenance management system maintains a database of information about the maintenance operations of organizations and automates the processing of equipment condition data to trigger maintenance planning, execution, and reporting.","implementation_level":"organization","parameters":[{"id":"ma-06.03_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"MA-06(03)-Examine"},{"method":"interview","label":"MA-06(03)-Interview"},{"method":"test","label":"MA-06(03)-Test"}],"is_enhancement":true,"parent_id":"MA-6"}]},{"id":"MA-7","oscal_id":"ma-7","family":"MA","title":"Field Maintenance","statement":"Restrict or prohibit field maintenance on <systems or system components> to <trusted maintenance facilities>.","supplemental_guidance":"Field maintenance is the type of maintenance conducted on a system or system component after the system or component has been deployed to a specific site (i.e., operational environment). In certain instances, field maintenance (i.e., local maintenance at the site) may not be executed with the same degree of rigor or with the same quality control checks as depot maintenance. For critical systems designated as such by the organization, it may be necessary to restrict or prohibit field maintenance at the local site and require that such maintenance be conducted in trusted facilities with additional controls.","implementation_level":"organization","parameters":[{"id":"ma-07_odp.01","label":"systems or system components"},{"id":"ma-07_odp.02","label":"trusted maintenance facilities"}],"methods":[{"method":"examine","label":"MA-07-Examine"},{"method":"interview","label":"MA-07-Interview"},{"method":"test","label":"MA-07-Test"}],"related_controls":["MA-2","MA-4","MA-5"]}]};
